import{_ as l,l as i,o as e,c as n,v as t,p as s,x as r,d as E,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"基底形貌与反射","description":"","frontmatter":{"title":"基底形貌与反射","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/topography-reflection.md","filePath":"litho/topography-reflection.md","lastUpdated":1789023840000}'),p={name:"litho/topography-reflection.md"};function B(c,a,A,C,f,m){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="基底形貌与反射" tabindex="-1">基底形貌与反射 <a class="header-anchor" href="#基底形貌与反射" aria-label="Permalink to &quot;基底形貌与反射&quot;">​</a></h1><div class="epigraph"><p>台阶让胶厚局域走进摆动横轴，又让界面不再是无限平面；反射有了散射和阴影，CD 跟着底下的地形走。</p><footer>—— 薄膜台阶与涂覆见 Mack、Levinson；散射接口对照 Born &amp; Wolf 的非平面界面</footer></div><p><a href="/litho/multilayer-barc">上一课</a>假定分层横向无限。缺口是：前层图形留下的<strong>台阶</strong>上，胶厚不是常数，BARC 覆盖不是常数，入射也不再是单一平面界面的 Fresnel。本课钉形貌对反射与 CD 的耦合。EUV 在强吸收、斜入射下的薄膜故事留给<a href="/litho/euv-thin-film-effects">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>旋涂在台阶上厚薄不均：凹槽里胶厚、凸台上胶薄，局部 \\(d\\) 在摆动曲线上走出一大段。即使 BARC 在平坦垫上 \\(|r|\\) 已小，台阶侧壁露出的金属或介质可以是另一张 \\(r\\)，局域驻波回到大振幅。散射：台阶棱是衍射物，把能量打进非镜方向，邻近图形的剂量被地形调制——看起来像 OPE，改照明却不如改平坦化。</p><p>缺口不是再选一次平坦垫上的胶厚工作点，而是：EPE 预算里与前层图形相关的 CD 项，有一部分是形貌光学，不是本层 TCC 没校准。</p><h3 id="平坦化与光学谁先" tabindex="-1">平坦化与光学谁先 <a class="header-anchor" href="#平坦化与光学谁先" aria-label="Permalink to &quot;平坦化与光学谁先&quot;">​</a></h3><p>化学机械抛光、多层 BARC 填平、旋涂硬掩模，先把 \\(d\\) 和界面拉回平面分层，本课的散射项才缩小。只加 OPC 偏置去跟每一个台阶，表不可穷尽，且换前层密度就作废。DTCO 放宽台阶高度，是在买光学，不只是买刻蚀。</p><p><span class="marginnote">调平传感器看到的是宏观形貌；台阶是微米以下的局域光学。全局调焦补不了凹槽里的 swing。不要把上一课序的场曲补偿用到这里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>诊断：在复现前层台阶的测试结构上量 CD vs 台阶高度 / 密度，对照平坦垫。改 BARC 填平能力，光学项应先动；改本层偶极，若曲线几乎不动，则不是禁戒节距。模拟：至少用局域厚度进薄膜矩阵；侧壁散射需要二维/三维电磁，紧凑 OPC 模型常常没有这一项——热点会表现为「模型外」的桥连。</p>',11)),(e(),s(d,null,{default:r(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E5%89%8D%E5%B1%82%E5%8F%B0%E9%98%B6%22%5D%20--%3E%20THK%5B%22%E5%B1%80%E5%9F%9F%E8%83%B6%E5%8E%9A%20%E2%86%92%20swing%22%5D%0A%20%20STEP%20--%3E%20SUB%5B%22%E4%BE%A7%E5%A3%81%E9%9C%B2%E5%87%BA%E5%8F%A6%E4%B8%80%E8%A1%AC%E5%BA%95%20r%22%5D%0A%20%20STEP%20--%3E%20SCT%5B%22%E6%A3%B1%E6%95%A3%E5%B0%84%20%2F%20%E9%82%BB%E8%BF%91%E5%89%82%E9%87%8F%22%5D%0A%20%20PLN%5B%22%E5%A1%AB%E5%B9%B3%20%2F%20CMP%22%5D%20--%3E%20FLAT%5B%22%E5%9B%9E%E5%88%B0%E5%B9%B3%E9%9D%A2%E5%88%86%E5%B1%82%22%5D%0A%20%20THK%20--%3E%20CD%5B%22%E5%9C%B0%E5%BD%A2%E7%9B%B8%E5%85%B3%20CD%22%5D%0A%20%20SUB%20--%3E%20CD%0A%20%20SCT%20--%3E%20CD%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="与横向核的边界" tabindex="-1">与横向核的边界 <a class="header-anchor" href="#与横向核的边界" aria-label="Permalink to &quot;与横向核的边界&quot;">​</a></h3><p>光学直径几个 \\(\\lambda/\\mathrm{NA}\\) 内的台阶都进邻近。稀疏大台阶以局域厚度为主；密栅上的浅台阶以有效介质和散射为主。报告必须声明台阶周期相对光学直径。矢量高 NA 对侧壁 s/p 更敏感，浸没层地形税往往大于干式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>局域 \\(d\\) 走摆动横轴，机制已在摆动课。侧壁作为倾斜界面，Fresnel 与阴影随照明方向变，偶极取向会让台阶一侧亮一侧暗，CD 左右不对称——易被误诊为彗差。散射光等效于额外的局部 flare，开阔区旁边的暗图形受害，与透镜晕光同类但源是晶圆地形。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CMP 工艺配方。三维电磁全芯片不可行，只能热点 clips。禁止把未公开的「台阶每纳米 CD」斜率当常数：它随 BARC 填平和 \\(|r|\\) 变。EUV 斜入射阴影与 DUV 台阶散射会叠在一起，拆到下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>台阶改变局域胶厚、露出的 \\(r\\) 和散射，CD 跟地形走。</li><li>先平坦化再谈本层 OPC；调焦补不了微台阶。</li><li>取向相关的不对称不要先归彗差。</li><li>紧凑模型常缺三维地形项，热点要 clips 验证。</li><li>下一课：EUV 波长下薄膜与吸收的另一套账。</li><li>出处：Mack；Levinson；Born &amp; Wolf。</li></ul>',8))])}const D=l(p,[["render",B]]);export{u as __pageData,D as default};
